-- Much Ado About Nothing currently has: 2025, Comedy, New Swan Theatre Festival, Spaghetti Western, Saloon Design, Shakespeare, Theatre Festival, Wild West (need to verify and add if < 5)
SET @much_ado_id = (SELECT id FROM projects WHERE title = 'Much Ado About Nothing' LIMIT 1);

INSERT INTO projectTags (projectId, tagId)
SELECT @much_ado_id, id FROM tags WHERE name IN ('American Southwest', 'Bluegrass Music', 'Romantic Comedy', 'Outdoor Theatre', 'Contemporary Setting')
ON DUPLICATE KEY UPDATE projectId = projectId;

